import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, migrate } from './db.ts';
import { HEARTBEAT_MS, MAX_ATTEMPTS, POLL_MS, RETRY_DELAY_MS, STEP_MS, type JobRow } from './jobs.ts';

const db = openDatabase();
migrate(db);

const heartbeat = db.prepare(
  `INSERT INTO heartbeats (name, ts) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET ts = excluded.ts`,
);
const claim = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ?
   WHERE seq = (SELECT seq FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1)
   RETURNING *`,
);
const setProgress = db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?');
const markCompleted = db.prepare(
  `UPDATE jobs SET status = 'completed', completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
);
const markFailed = db.prepare(
  `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ?`,
);
const requeue = db.prepare(
  `UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ?`,
);
const requeueInterrupted = db.prepare(
  `UPDATE jobs SET status = 'queued', completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`,
);
const clearHeartbeat = db.prepare("DELETE FROM heartbeats WHERE name = 'worker'");

let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const nowIso = () => new Date().toISOString();

// A job left `running` means the previous worker died mid-attempt. Put it back in the queue so it is
// processed again. The interrupted attempt stays counted in `attempts`.
const recovered = Number(requeueInterrupted.run(nowIso()).changes);
if (recovered > 0) console.log(`requeued ${recovered} interrupted job(s)`);

function beat(): void {
  try {
    heartbeat.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}
beat();
const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);

/** Runs one attempt of a claimed job. Returns early, leaving it `running`, if the worker is stopping. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure at the first step, before any progress.
    await sleep(STEP_MS);
    if (stopping) return;
    if (attempt >= MAX_ATTEMPTS) markFailed.run('transient failure', nowIso(), job.id);
    else requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    setProgress.run(step, nowIso(), job.id);
  }
  markCompleted.run(job.input.toUpperCase(), nowIso(), job.id);
}

async function loop(): Promise<void> {
  while (!stopping) {
    let job: JobRow | undefined;
    try {
      job = claim.get(nowIso(), Date.now()) as JobRow | undefined;
    } catch (e) {
      console.error('claim failed:', e);
    }
    if (!job) {
      await sleep(POLL_MS);
      continue;
    }
    try {
      await runAttempt(job);
    } catch (e) {
      console.error(`attempt for job ${job.id} failed:`, e);
      await sleep(POLL_MS);
    }
  }
}

console.log('worker started');
await loop();

clearInterval(heartbeatTimer);
try {
  clearHeartbeat.run();
} catch {
  // best effort: health falls back to heartbeat staleness
}
db.close();
console.log('worker stopped');

