import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, migrate } from './db.ts';
import { HEARTBEAT_STALE_MS, toJob, type JobRow } from './jobs.ts';

const db = openDatabase();
migrate(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, available_at, idempotency_key, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?, ?)`,
);
const jobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const jobByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const listAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const workerHeartbeat = db.prepare("SELECT ts FROM heartbeats WHERE name = 'worker'");

const MAX_BODY_BYTES = 64 * 1024;
const MAX_INPUT_LENGTH = 1000;
const MAX_STEPS = 20;
const MAX_FAIL_ATTEMPTS = 5;
const DEFAULT_STEPS = 5;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

type Validation = { ok: true; payload: Payload; key: string | null } | { ok: false; fields: FieldError[] };

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function readInteger(
  obj: Record<string, unknown>,
  field: 'steps' | 'failAttempts',
  def: number,
  min: number,
  max: number,
  errors: FieldError[],
): number {
  if (!Object.hasOwn(obj, field)) return def;
  const v = obj[field];
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    errors.push({ field, message: `must be an integer from ${min} to ${max}` });
    return def;
  }
  return v;
}

function validate(req: IncomingMessage, text: string, tooLarge: boolean): Validation {
  const errors: FieldError[] = [];

  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    if (KEY_RE.test(rawKey)) key = rawKey;
    else errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = req.headers['content-type']?.split(';')[0]?.trim().toLowerCase();
  if (mediaType !== 'application/json') errors.push({ field: 'body', message: 'Content-Type must be application/json' });

  let parsed: unknown;
  if (tooLarge) {
    errors.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    try {
      parsed = JSON.parse(text);
    } catch {
      errors.push({ field: 'body', message: 'body must be valid JSON' });
    }
  }

  if (parsed !== undefined && !isPlainObject(parsed)) {
    errors.push({ field: 'body', message: 'body must be a JSON object' });
  }

  if (!isPlainObject(parsed)) return { ok: false, fields: errors };
  const obj = parsed;

  for (const name of Object.keys(obj)) {
    if (!KNOWN_FIELDS.has(name)) errors.push({ field: name, message: 'unknown field' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof obj.input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (obj.input.trim() === '') {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = obj.input;
  }

  const steps = readInteger(obj, 'steps', DEFAULT_STEPS, 1, MAX_STEPS, errors);
  const failAttempts = readInteger(obj, 'failAttempts', 0, 0, MAX_FAIL_ATTEMPTS, errors);

  if (errors.length > 0) return { ok: false, fields: errors };
  return { ok: true, payload: { input, steps, failAttempts }, key };
}

function samePayload(job: JobRow, p: Payload): boolean {
  return job.input === p.input && job.steps === p.steps && job.fail_attempts === p.failAttempts;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const v = validate(req, text, tooLarge);
  if (!v.ok) {
    sendError(res, 400, 'invalid_request', `Invalid request: ${v.fields.map((f) => f.field).join(', ')}.`, v.fields);
    return;
  }

  const { payload, key } = v;
  const now = new Date().toISOString();
  let status: number;
  let body: unknown;

  // BEGIN IMMEDIATE makes the key lookup and the insert one atomic step, so a key never yields two jobs.
  db.exec('BEGIN IMMEDIATE');
  try {
    const existing = key !== null ? (jobByKey.get(key) as JobRow | undefined) : undefined;
    if (existing) {
      if (samePayload(existing, payload)) {
        status = 200;
        body = toJob(existing);
      } else {
        status = 409;
        body = { error: { code: 'idempotency_conflict', message: 'Idempotency-Key was already used with a different payload.' } };
      }
    } else {
      const id = randomUUID();
      insertJob.run(id, payload.input, payload.steps, payload.failAttempts, key, now, now);
      status = 201;
      body = toJob(jobById.get(id) as JobRow);
    }
    db.exec('COMMIT');
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
  send(res, status, body);
}

function health(res: ServerResponse): void {
  const row = workerHeartbeat.get() as { ts: number } | undefined;
  const up = row !== undefined && Date.now() - Number(row.ts) <= HEARTBEAT_STALE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function route(req: IncomingMessage, res: ServerResponse): Promise<void> | void {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
    return health(res);
  }
  if (pathname === '/') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: (listAll.all() as unknown as JobRow[]).map(toJob) });
    if (method === 'POST') return createJob(req, res);
    res.setHeader('allow', 'GET, POST');
    return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') {
      res.setHeader('allow', 'GET');
      return sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
    }
    const row = jobById.get(decodeURIComponent(match[1]!)) as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  return sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => route(req, res))
    .catch((e: unknown) => {
      console.error('request failed:', e);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

